+const signTestInterpretation = (
+  summary: Summary,
+  labelA: string,
+  labelB: string,
+): string => {
+  if (summary.signTestP >= 0.05) return "not distinguishable from noise";
+  return summary.b > summary.a ? `${labelB} is better` : `${labelB} is worse`;
+};
